<script setup>
import {computed,inject,onMounted,ref} from 'vue';
import {call} from '../api';
import {namecardDesign,namecardRanges} from '../../server/namecard-model.mjs';
const {draft:d,notify}=inject('studio'),fonts=ref([]),design=computed(()=>namecardDesign(d.value.edit));
function update(value){d.value.edit.cardDesign={...design.value,...value};}
function number(key,event){const value=Number(event.target.value),[min,max]=namecardRanges[key];if(Number.isFinite(value))update({[key]:Math.min(max,Math.max(min,value))});}
function font(event){const f=fonts.value.find(f=>f.id===event.target.value);if(f)update({fontId:f.id,fontFamily:f.family});}
function color(key,event){if(/^#[a-f\d]{6}$/i.test(event.target.value))update({[key]:event.target.value.toUpperCase()});else{event.target.value=design.value[key];notify('名片颜色请输入六位十六进制色值','error');}}
onMounted(async()=>{try{fonts.value=await call('listSubtitleFonts');}catch(error){notify(error.message,'error');}});
const rows=[['offsetX','左侧距离',2],['offsetY','底部距离',2]],textRows=[['opacity','透明度',.05],['letterSpacing','字间距',1],['lineSpacing','行间距',1]],backgroundRows=[['backgroundOpacity','透明度',.05],['backgroundPaddingX','背景宽度',2],['backgroundPaddingY','背景高度',2],['backgroundRadius','圆角',1]];
const displayValue=(key,value)=>key.includes('Opacity')||key==='opacity'?Math.round(value*100)+'%':value;
</script>
<template>
 <div class="namecard-panel"><header><h3>个人名片</h3><p>{{d.edit.cardEnabled?'已开启':'已关闭'}}</p></header><div class="namecard-panel-scroll">
  <div class="namecard-text-grid"><label><span>称呼</span><input v-model="d.edit.cardName" aria-label="名片称呼" placeholder="人物称呼" maxlength="500"/></label><label><span>简介</span><textarea v-model="d.edit.cardDescription" aria-label="名片简介" placeholder="简单介绍，可输入多行" maxlength="10000" rows="2"/></label></div>
  <div class="namecard-option-row"><span>显示时长</span><div class="segmented" role="group" aria-label="名片显示时长"><button :class="{active:design.displayMode==='always'}" :aria-pressed="design.displayMode==='always'" @click="update({displayMode:'always'})">一直显示</button><button :class="{active:design.displayMode==='duration'}" :aria-pressed="design.displayMode==='duration'" @click="update({displayMode:'duration'})">显示几秒</button></div></div>
  <label v-if="design.displayMode==='duration'" class="namecard-duration"><input :value="design.duration" type="number" min="1" max="60" aria-label="名片显示秒数" @change="number('duration',$event)"/><span>秒</span></label>
  <section class="namecard-style-card"><header><strong>位置</strong><small>可在右侧编辑预览中拖动调整</small></header><div class="namecard-field-grid"><label v-for="[key,label,step] in rows" :key="key"><span>{{label}}</span><div class="namecard-slider-row"><input :value="design[key]" type="range" :min="namecardRanges[key][0]" :max="namecardRanges[key][1]" :step="step" :aria-label="'名片'+label" @input="number(key,$event)"/><output>{{design[key]}}</output></div></label></div></section>
  <section class="namecard-style-card"><header><strong>文字</strong><small>字体、颜色、透明度和间距</small></header><div class="namecard-field-grid"><label><span>字体</span><select :value="design.fontId||fonts.find(f=>f.family===design.fontFamily)?.id||''" aria-label="名片字体" @change="font"><option v-if="!fonts.length" value="">{{design.fontFamily}}</option><option v-for="f in fonts" :key="f.id" :value="f.id">{{f.label}}</option></select></label><label><span>字号</span><div class="namecard-slider-row"><input :value="design.fontSize" type="range" min="18" max="80" step="1" aria-label="名片字号" @input="number('fontSize',$event)"/><output>{{design.fontSize}}</output></div></label></div><label class="namecard-bold"><input :checked="design.nameBold" type="checkbox" aria-label="名片称呼加粗" @change="update({nameBold:$event.target.checked})"/><span>称呼加粗</span></label><label class="namecard-color"><span>文字颜色</span><div class="namecard-color-inputs"><input :value="design.textColor" type="color" aria-label="名片文字颜色" @input="update({textColor:$event.target.value})"/><input :value="design.textColor" aria-label="名片文字色值" maxlength="7" @change="color('textColor',$event)"/></div></label><label v-for="[key,label,step] in textRows" :key="key"><span>{{label}}</span><div class="namecard-slider-row"><input :value="design[key]" type="range" :min="namecardRanges[key][0]" :max="namecardRanges[key][1]" :step="step" :aria-label="'名片文字'+label" @input="number(key,$event)"/><output>{{displayValue(key,design[key])}}</output></div></label></section>
  <section class="namecard-style-card"><header><strong>背景</strong><small>颜色、透明度和尺寸</small></header><label class="namecard-color"><span>背景颜色</span><div class="namecard-color-inputs"><input :value="design.backgroundColor" type="color" aria-label="名片背景颜色" @input="update({backgroundColor:$event.target.value})"/><input :value="design.backgroundColor" aria-label="名片背景色值" maxlength="7" @change="color('backgroundColor',$event)"/></div></label><label v-for="[key,label,step] in backgroundRows" :key="key"><span>{{label}}</span><div class="namecard-slider-row"><input :value="design[key]" type="range" :min="namecardRanges[key][0]" :max="namecardRanges[key][1]" :step="step" :aria-label="'名片背景'+label" @input="number(key,$event)"/><output>{{displayValue(key,design[key])}}</output></div></label></section>
 </div></div>
</template>
